import { formatMarks, withOrigin, type BlockJSON, type FormatMark, type InlineJSON, type Manuscript, type TextJSON } from './model'

// A manuscript travels to the translator as its chosen wording only: one entry
// per paragraph or heading with words, its bold, italic and underline written
// as <b>, <i> and <u>. The translation comes back the same way and becomes a
// new manuscript whose every character is marked as generated by AI.
export interface SourceBlock { id: string; text: string }
export interface TranslationSource { title: string; blocks: SourceBlock[] }
export interface TranslationResult { title: string; blocks: SourceBlock[] }

const TAG: Record<FormatMark['type'], string> = { strong: 'b', em: 'i', highlight: 'u' }
const MARK: Record<string, FormatMark['type']> = { b: 'strong', i: 'em', u: 'highlight' }
const ORDER: FormatMark['type'][] = ['strong', 'em', 'highlight']
const escape = (text: string) => text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
const unescape = (text: string) => text.replace(/&(lt|gt|quot|#39|amp);/g, (_, name: string) => ({ lt: '<', gt: '>', quot: '"', '#39': "'", amp: '&' })[name]!)

function chosenRuns(nodes: InlineJSON[] = []): TextJSON[] {
  return nodes.flatMap(node => node.type === 'text' ? [node] : chosenRuns(node.content))
}
export function taggedText(block: BlockJSON): string {
  return chosenRuns(block.content).map(run => {
    const marks = ORDER.filter(type => formatMarks(run.marks).some(mark => mark.type === type))
    return marks.map(type => '<' + TAG[type] + '>').join('') + escape(run.text) + [...marks].reverse().map(type => '</' + TAG[type] + '>').join('')
  }).join('')
}
const hasWords = (block: BlockJSON) => chosenRuns(block.content).some(run => run.text.trim())

// Short ids (p1, p2…) keep the request small; blank paragraphs stay home.
export function translationSource(doc: Manuscript, title: string): TranslationSource {
  return { title, blocks: doc.content.flatMap((block, index) => hasWords(block) ? [{ id: 'p' + (index + 1), text: taggedText(block) }] : []) }
}

// Parts of about maxWords words, so long manuscripts translate in steps.
export function translationParts(blocks: SourceBlock[], maxWords = 3000): SourceBlock[][] {
  const parts: SourceBlock[][] = []
  let words = 0
  for (const block of blocks) {
    const count = block.text.split(/\s+/).filter(Boolean).length
    if (!parts.length || (words + count > maxWords && parts.at(-1)!.length)) { parts.push([]); words = 0 }
    parts.at(-1)!.push(block)
    words += count
  }
  return parts
}

// Tags the translator returns become marks again; anything else is text.
export function parseTagged(text: string): TextJSON[] {
  const runs: TextJSON[] = []
  const open: Record<FormatMark['type'], number> = { strong: 0, em: 0, highlight: 0 }
  let at = 0
  const push = (raw: string) => {
    if (!raw) return
    const marks = ORDER.filter(type => open[type] > 0).map(type => ({ type }))
    const previous = runs.at(-1)
    const value = unescape(raw)
    if (previous && JSON.stringify(previous.marks ?? []) === JSON.stringify(marks)) previous.text += value
    else runs.push(marks.length ? { type: 'text', text: value, marks } : { type: 'text', text: value })
  }
  for (const tag of text.matchAll(/<(\/?)([biu])>/g)) {
    push(text.slice(at, tag.index))
    const type = MARK[tag[2]]
    open[type] = Math.max(0, open[type] + (tag[1] ? -1 : 1))
    at = tag.index + tag[0].length
  }
  push(text.slice(at))
  return runs
}

// The translated manuscript keeps the original's paragraphs and headings in
// order, with new ids. A translation that lost, merged or invented paragraphs
// is refused rather than quietly misaligned.
export function translatedManuscript(original: Manuscript, source: TranslationSource, result: TranslationResult): Manuscript {
  const translated = new Map(result.blocks.map(block => [block.id, block.text]))
  const sent = new Set(source.blocks.map(block => block.id))
  if (translated.size !== result.blocks.length || result.blocks.some(block => !sent.has(block.id)) || [...sent].some(id => !translated.has(id))) {
    throw Error('The translation lost or merged paragraphs. Translate again.')
  }
  const content = original.content.map((block, index): BlockJSON => {
    const id = crypto.randomUUID()
    const attrs = block.type === 'heading' ? { id, level: block.attrs.level ?? 1 } : { id }
    const text = translated.get('p' + (index + 1))
    const runs = text === undefined ? [] : withOrigin(parseTagged(text.trim()), 'ai')
    return { type: block.type, attrs, ...(runs.length ? { content: runs } : {}) }
  })
  return { type: 'doc', content }
}
